//! Verification tests for shared constants.
//!
//! These tests ensure that all pre-computed SHA-256 hashes in `pda_seeds`
//! actually match `SHA-256(struct_name)`.
//!
//! AUTO-GENERATED by solana-program-builder step 15. Do not edit manually.

use sha2::{Digest, Sha256};

use crate::pda_seeds;

fn sha256_of(name: &str) -> [u8; 32] {
    let result = Sha256::digest(name.as_bytes());
    result.into()
}

macro_rules! verify_seed {
    ($name:expr, $constant:expr) => {
        let expected = sha256_of($name);
        assert_eq!(
            $constant, expected,
            "PDA seed mismatch for '{}': constant does not match SHA-256(\"{}\")",
            $name, $name
        );
    };
}

#[test]
fn test_global_accounts_seeds() {
    verify_seed!("AdminWallet", pda_seeds::ADMIN_WALLET_SEED);
    verify_seed!("LotteryConfig", pda_seeds::LOTTERY_CONFIG_SEED);
    verify_seed!("NetworkKey", pda_seeds::NETWORK_KEY_SEED);
    verify_seed!("ProtocolConfig", pda_seeds::PROTOCOL_CONFIG_SEED);
}

